    # Create a mapping from original index to value
    original_to_value = {i: val for i, val in enumerate(arr)}

    n = len(arr)
    adj = {i: [] for i in range(n)}
    in_degree = {i: 0 for i in range(n)}

    for i, j in preserve_pairs:
        adj[i].append(j)
        in_degree[j] += 1

    # Kahn's algorithm for topological sort
    queue = [i for i in range(n) if in_degree[i] == 0]
    result_indices = []

    while queue:
        # Sort queue to ensure deterministic behavior
        queue.sort()
        u = queue.pop(0)
        result_indices.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Check for cycle (though problem implies valid solution)
    if len(result_indices) != n:
        return sorted(arr)

